/* fdtd-2d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "fdtd-2d.h"

/* --------------------------------------------------------------------
 * Tunable parameters for the optimized kernel.
 *
 * FDTD_UNROLL_FACTOR controls the unroll hint used for the innermost
 * loops.  It can be adjusted at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DFDTD_UNROLL_FACTOR=16 ...
 *
 * to better match a particular micro-architecture.
 * -------------------------------------------------------------------- */
#ifndef FDTD_UNROLL_FACTOR
# define FDTD_UNROLL_FACTOR 8
#endif


/* Array initialization.
 *
 * Optimization notes:
 *  - We create restrict-qualified, linear pointers to the 2D arrays to
 *    make aliasing explicit and enable better vectorization.
 *  - We traverse the 2D arrays in row-major order with a stride-1
 *    inner loop to maximize cache-line utilization and prefetching.
 */
static
void init_array (int tmax,
		 int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  /* Linear, restrict-qualified views of the arrays.
     &ex[0][0] works for both static and VLA-based PolyBench layouts. */
  DATA_TYPE *restrict ex_data   = &ex[0][0];
  DATA_TYPE *restrict ey_data   = &ey[0][0];
  DATA_TYPE *restrict hz_data   = &hz[0][0];
  DATA_TYPE *restrict fict_data = _fict_;

  /* Initialize fictitious source term. */
  for (int i = 0; i < tmax; i++)
    fict_data[i] = (DATA_TYPE) i;

  /* Initialize field arrays.
     We keep a stride-1 inner loop over j to favor vectorization. */
  DATA_TYPE *restrict ex_row = ex_data;
  DATA_TYPE *restrict ey_row = ey_data;
  DATA_TYPE *restrict hz_row = hz_data;

  for (int i = 0; i < nx; i++)
    {
      for (int j = 0; j < ny; j++)
      {
        ex_row[j] = ((DATA_TYPE) i * (j + 1)) / nx;
        ey_row[j] = ((DATA_TYPE) i * (j + 2)) / ny;
        hz_row[j] = ((DATA_TYPE) i * (j + 3)) / nx;
      }

      /* Move to the next row. */
      ex_row += ny;
      ey_row += ny;
      hz_row += ny;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("ex");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ex[i][j]);
    }
  POLYBENCH_DUMP_END("ex");
  POLYBENCH_DUMP_FINISH;

  POLYBENCH_DUMP_BEGIN("ey");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ey[i][j]);
    }
  POLYBENCH_DUMP_END("ey");

  POLYBENCH_DUMP_BEGIN("hz");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, hz[i][j]);
    }
  POLYBENCH_DUMP_END("hz");
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimization strategy:
 *  - Use restrict-qualified, linearized views of the 2D arrays to give
 *    the compiler strong aliasing guarantees.
 *  - Keep the innermost loops as simple stride-1 traversals to exploit
 *    spatial locality and enable SIMD vectorization.
 *  - Hoist constants out of loops.
 *  - Provide GCC-specific vectorization hints (#pragma GCC ivdep and
 *    #pragma GCC unroll) while preserving original numerical semantics.
 */
static __attribute__((flatten, noinline))
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  /* Linear, restrict-qualified views of the fields.  Using &a[0][0]
     makes this independent of whether PolyBench uses C99 VLAs or
     fixed-size arrays for the 2D layout. */
  DATA_TYPE *restrict ex_data   = &ex[0][0];
  DATA_TYPE *restrict ey_data   = &ey[0][0];
  DATA_TYPE *restrict hz_data   = &hz[0][0];
  DATA_TYPE *restrict fict_data = _fict_;

  /* PolyBench-provided loop bounds; may differ from nominal sizes
     when running in reduced-size or test modes. */
  const int tmax_bound = _PB_TMAX;
  const int nx_bound   = _PB_NX;
  const int ny_bound   = _PB_NY;

  /* Precompute scalar coefficients to avoid recomputation. */
  const DATA_TYPE c0 = SCALAR_VAL(0.5);
  const DATA_TYPE c1 = SCALAR_VAL(0.7);

#pragma scop

  for (int t = 0; t < tmax_bound; ++t)
    {
      const DATA_TYPE fict_val = fict_data[t];

      /* ------------------------------------------------------------
       * ey[0][j] = _fict_[t]
       * Boundary condition on the first row of ey.
       * ------------------------------------------------------------ */
      {
        DATA_TYPE *restrict ey_row0 = ey_data; /* row i = 0 */

#pragma GCC ivdep
#pragma GCC unroll FDTD_UNROLL_FACTOR
        for (int j = 0; j < ny_bound; ++j)
          ey_row0[j] = fict_val;
      }

      /* ------------------------------------------------------------
       * ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
       * for i = 1 .. nx-1, j = 0 .. ny-1
       * Each (i,j) depends only on hz, which is read-only in this
       * loop, so the inner j-loop is fully vectorizable.
       * ------------------------------------------------------------ */
      {
        DATA_TYPE *restrict ey_row      = ey_data + ny_bound; /* row 1 */
        DATA_TYPE *restrict hz_row      = hz_data + ny_bound; /* row 1 */
        DATA_TYPE *restrict hz_prev_row = hz_data;            /* row 0 */

        for (int i = 1; i < nx_bound; ++i)
          {
#pragma GCC ivdep
#pragma GCC unroll FDTD_UNROLL_FACTOR
            for (int j = 0; j < ny_bound; ++j)
              ey_row[j] -= c0 * (hz_row[j] - hz_prev_row[j]);

            /* Advance to next row. */
            ey_row      += ny_bound;
            hz_prev_row += ny_bound;
            hz_row      += ny_bound;
          }
      }

      /* ------------------------------------------------------------
       * ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
       * for i = 0 .. nx-1, j = 1 .. ny-1
       * hz is read-only in this loop; there are no loop-carried
       * dependencies across j, so vectorization is safe.
       * ------------------------------------------------------------ */
      {
        DATA_TYPE *restrict ex_row = ex_data;
        DATA_TYPE *restrict hz_row = hz_data;

        for (int i = 0; i < nx_bound; ++i)
          {
#pragma GCC ivdep
#pragma GCC unroll FDTD_UNROLL_FACTOR
            for (int j = 1; j < ny_bound; ++j)
              ex_row[j] -= c0 * (hz_row[j] - hz_row[j-1]);

            ex_row += ny_bound;
            hz_row += ny_bound;
          }
      }

      /* ------------------------------------------------------------
       * hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
       *                               + ey[i+1][j] - ey[i][j])
       * for i = 0 .. nx-2, j = 0 .. ny-2
       * Reads ex and ey (already updated this time step) and writes
       * hz.  Each j-iteration is independent, enabling SIMD.
       * ------------------------------------------------------------ */
      {
        DATA_TYPE *restrict hz_row      = hz_data;
        DATA_TYPE *restrict ex_row      = ex_data;
        DATA_TYPE *restrict ey_row      = ey_data;
        DATA_TYPE *restrict ey_row_next = ey_data + ny_bound;

        for (int i = 0; i < nx_bound - 1; ++i)
          {
#pragma GCC ivdep
#pragma GCC unroll FDTD_UNROLL_FACTOR
            for (int j = 0; j < ny_bound - 1; ++j)
              hz_row[j] -= c1 * ((ex_row[j+1]   - ex_row[j]) +
                                 (ey_row_next[j] - ey_row[j]));

            hz_row      += ny_bound;
            ex_row      += ny_bound;
            ey_row      += ny_bound;
            ey_row_next += ny_bound;
          }
      }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
	      POLYBENCH_ARRAY(ex),
	      POLYBENCH_ARRAY(ey),
	      POLYBENCH_ARRAY(hz),
	      POLYBENCH_ARRAY(_fict_));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_fdtd_2d (tmax, nx, ny,
		  POLYBENCH_ARRAY(ex),
		  POLYBENCH_ARRAY(ey),
		  POLYBENCH_ARRAY(hz),
		  POLYBENCH_ARRAY(_fict_));


  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nx, ny, POLYBENCH_ARRAY(ex),
				    POLYBENCH_ARRAY(ey),
				    POLYBENCH_ARRAY(hz)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(ex);
  POLYBENCH_FREE_ARRAY(ey);
  POLYBENCH_FREE_ARRAY(hz);
  POLYBENCH_FREE_ARRAY(_fict_);

  return 0;
}
