/* Main computational kernel. The whole function will be timed,
   including the call and return.

   This version reorganizes the computation to improve cache locality
   and enable better vectorization while preserving the original
   numerical semantics.

   Key ideas:
   - Use restrict-qualified, aligned aliases for the main arrays to
     help the compiler with alias analysis and vectorization.
   - Precompute scalar constants.
   - Reorder and pipeline the Ex/Ey/Hz updates along the x-dimension (i)
     so that Hz[i,*] is updated as soon as Ex[i,*], Ey[i,*], Ey[i+1,*]
     are available, improving temporal locality.
   - Carefully maintain the original data dependencies:
       * Ex[i,*] depends only on old Hz[i,*].
       * Ey[i,*] depends only on old Hz[i,*] and Hz[i-1,*].
       * Hz[i,*] depends on new Ex[i,*], Ey[i,*], Ey[i+1,*].
*/
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

  /* Normalized sizes used by PolyBench. These may differ from the
     nominal parameters in case of parameterized problem sizes. */
  const int tmax_size = _PB_TMAX;
  const int nx_size   = _PB_NX;
  const int ny_size   = _PB_NY;

  /* Create restrict-qualified, aligned aliases.  PolyBench allocates
     data with a large alignment (typically 4096 bytes), so we can
     safely tell the compiler about this to help vectorization. */
  DATA_TYPE (* restrict ex_)[ny_size] =
    (DATA_TYPE (*)[ny_size])__builtin_assume_aligned(ex, 64);
  DATA_TYPE (* restrict ey_)[ny_size] =
    (DATA_TYPE (*)[ny_size])__builtin_assume_aligned(ey, 64);
  DATA_TYPE (* restrict hz_)[ny_size] =
    (DATA_TYPE (*)[ny_size])__builtin_assume_aligned(hz, 64);
  DATA_TYPE * restrict fict_ =
    (DATA_TYPE *)__builtin_assume_aligned(_fict_, 64);

  /* Hoist scalar constants out of the loops. */
  const DATA_TYPE half         = SCALAR_VAL(0.5);
  const DATA_TYPE seven_tenths = SCALAR_VAL(0.7);

#pragma scop

  for (t = 0; t < tmax_size; t++)
    {
      const DATA_TYPE fict_val = fict_[t];

      /* 1. Boundary condition on Ey: first row set from _fict_. */
      {
        DATA_TYPE * restrict ey_row0 = ey_[0];
        for (j = 0; j < ny_size; j++)
          ey_row0[j] = fict_val;
      }

      /* The following code implements a pipelined update along i:

         Original (per time-step):

           ey[0][*] = _fict_[t];
           for i=1..NX-1: ey[i][*] = ey[i][*] - 0.5*(hz[i][*]-hz[i-1][*]);
           for i=0..NX-1, j>=1: ex[i][j] = ex[i][j] - 0.5*(hz[i][j]-hz[i][j-1]);
           for i=0..NX-2, j>=0: hz[i][j] = hz[i][j]
                                - 0.7*(ex[i][j+1]-ex[i][j]
                                       + ey[i+1][j]-ey[i][j]);

         Reordered schedule used here (still within the same time-step):

           1) Ey[0,*] boundary (above).
           2) Ex[0,*]      from old Hz[0,*].
           3) Ey[1,*]      from old Hz[1,*] and old Hz[0,*].
           4) Hz[0,*]      from new Ex[0,*], Ey[0,*], Ey[1,*].
           5) For i = 1 .. NX-2:
                5a) Ex[i,*]   from old Hz[i,*].
                5b) Ey[i+1,*] from old Hz[i+1,*] and old Hz[i,*].
                5c) Hz[i,*]   from new Ex[i,*], Ey[i,*], Ey[i+1,*].
           6) Ex[NX-1,*]  from old Hz[NX-1,*] (not used by Hz in this step).

         All data dependencies are preserved, and every access that in the
         original code saw an "old" value still does so here.  The benefit
         is that Hz[i,*] is computed soon after the necessary Ex/Ey rows,
         which improves spatial and temporal locality.
      */

      /* 2. Ex row 0: uses only old Hz[0,*].  j starts at 1, j=0 unchanged. */
      if (ny_size > 1)
      {
        DATA_TYPE * restrict ex_row0 = ex_[0];
        DATA_TYPE * restrict hz_row0 = hz_[0];

        DATA_TYPE hz_left = hz_row0[0];
        for (j = 1; j < ny_size; j++)
        {
          DATA_TYPE hz_center = hz_row0[j];
          ex_row0[j] -= half * (hz_center - hz_left);
          hz_left = hz_center;
        }
      }

      /* 3. Ey row 1: uses old Hz[1,*] and old Hz[0,*]. */
      if (nx_size > 1)
      {
        DATA_TYPE * restrict ey_row1 = ey_[1];
        DATA_TYPE * restrict hz_row0 = hz_[0];
        DATA_TYPE * restrict hz_row1 = hz_[1];

        for (j = 0; j < ny_size; j++)
          ey_row1[j] -= half * (hz_row1[j] - hz_row0[j]);
      }

      /* 4. Hz row 0: uses new Ex[0,*], new Ey[0,*], new Ey[1,*]. */
      if (nx_size > 1 && ny_size > 1)
      {
        DATA_TYPE * restrict hz_row0 = hz_[0];
        DATA_TYPE * restrict ex_row0 = ex_[0];
        DATA_TYPE * restrict ey_row0 = ey_[0];
        DATA_TYPE * restrict ey_row1 = ey_[1];

        for (j = 0; j < ny_size - 1; j++)
        {
          const DATA_TYPE ex_diff = ex_row0[j+1] - ex_row0[j];
          const DATA_TYPE ey_diff = ey_row1[j]   - ey_row0[j];
          hz_row0[j] -= seven_tenths * (ex_diff + ey_diff);
        }
      }

      /* 5. Pipelined updates for interior rows: i = 1 .. nx_size-2.
             Each iteration updates:
               - Ex[i,*]   (from old Hz[i,*])
               - Ey[i+1,*] (from old Hz[i+1,*], old Hz[i,*])
               - Hz[i,*]   (from new Ex[i,*], Ey[i,*], Ey[i+1,*])
      */
      for (i = 1; i < nx_size - 1; i++)
      {
        /* 5a. Ex row i: from old Hz[i,*]. */
        if (ny_size > 1)
        {
          DATA_TYPE * restrict ex_row = ex_[i];
          DATA_TYPE * restrict hz_row = hz_[i];

          DATA_TYPE hz_left = hz_row[0];
          for (j = 1; j < ny_size; j++)
          {
            DATA_TYPE hz_center = hz_row[j];
            ex_row[j] -= half * (hz_center - hz_left);
            hz_left = hz_center;
          }
        }

        /* 5b. Ey row i+1: from old Hz[i+1,*] and old Hz[i,*]. */
        DATA_TYPE * restrict ey_row_ip1 = ey_[i+1];
        DATA_TYPE * restrict hz_row_i   = hz_[i];
        DATA_TYPE * restrict hz_row_ip1 = hz_[i+1];

        for (j = 0; j < ny_size; j++)
          ey_row_ip1[j] -= half * (hz_row_ip1[j] - hz_row_i[j]);

        /* 5c. Hz row i: from new Ex[i,*], Ey[i,*], Ey[i+1,*]. */
        if (ny_size > 1)
        {
          DATA_TYPE * restrict hz_row_w = hz_row_i;  /* writable Hz row i   */
          DATA_TYPE * restrict ex_row   = ex_[i];
          DATA_TYPE * restrict ey_row_i = ey_[i];

          for (j = 0; j < ny_size - 1; j++)
          {
            const DATA_TYPE ex_diff = ex_row[j+1]   - ex_row[j];
            const DATA_TYPE ey_diff = ey_row_ip1[j] - ey_row_i[j];
            hz_row_w[j] -= seven_tenths * (ex_diff + ey_diff);
          }
        }
      }

      /* 6. Last Ex row (nx_size-1): from old Hz[nx_size-1,*].
         This row is *not* used by Hz updates in this step (since Hz
         only updates rows 0..nx_size-2), but its updated values are
         required as input for the next time-step.  For NY <= 1, the
         original inner loop is empty, which we preserve. */
      if (nx_size > 1 && ny_size > 1)
      {
        const int last_i = nx_size - 1;
        DATA_TYPE * restrict ex_row_last = ex_[last_i];
        DATA_TYPE * restrict hz_row_last = hz_[last_i];

        DATA_TYPE hz_left = hz_row_last[0];
        for (j = 1; j < ny_size; j++)
        {
          DATA_TYPE hz_center = hz_row_last[j];
          ex_row_last[j] -= half * (hz_center - hz_left);
          hz_left = hz_center;
        }
      }
      else if (nx_size > 1 && ny_size <= 1)
      {
        /* Degenerate case NY <= 1:
           In the original code, the Ex update loops have j starting at 1,
           so they are empty; we intentionally do nothing here as well. */
      }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
