/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static void __attribute__((noinline))
kernel_fdtd_2d(int tmax,
	       int nx,
	       int ny,
	       DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
	       DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
	       DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
	       DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  /* Parameters are kept to preserve the original interface; the actual
     loop bounds use the PolyBench loop-bound macros, as in the original. */
  (void)tmax;
  (void)nx;
  (void)ny;

  /* Make the loop bounds explicit constants inside the kernel.
     This helps the compiler optimize and matches the original behavior
     that used _PB_* macros directly in the loops. */
  const int tmax_ = _PB_TMAX;
  const int nx_   = _PB_NX;
  const int ny_   = _PB_NY;

  /* Hoist scalar constants out of the loops.  SCALAR_VAL handles the
     DATA_TYPE and fixed-point vs floating-point configurations. */
  const DATA_TYPE half = SCALAR_VAL(0.5);
  const DATA_TYPE c0_7 = SCALAR_VAL(0.7);

  int t;

#pragma scop

  /* Parallelize the spatial loops with OpenMP.
     - The outer time loop remains sequential because each step depends
       on the previous one.
     - When compiled without OpenMP support, all '#pragma omp' directives
       are ignored and the code executes exactly as a sequential program. */
#pragma omp parallel
  {
    for (t = 0; t < tmax_; t++)
    {
      /* 1. Apply boundary condition on the first row of ey. */
#pragma omp for schedule(static)
      for (int j = 0; j < ny_; j++)
      {
        ey[0][j] = _fict_[t];
      }

      /* 2. Update ey in the interior.
         Each (i,j) update is independent: ey[i][j] depends only on
         ey[i][j], hz[i][j], and hz[i-1][j].  We parallelize over rows
         (i) to keep inner loops over the contiguous j-dimension. */
#pragma omp for schedule(static)
      for (int i = 1; i < nx_; i++)
      {
        DATA_TYPE * restrict ey_row      = ey[i];
        DATA_TYPE * restrict hz_row      = hz[i];
        DATA_TYPE * restrict hz_row_prev = hz[i - 1];

        /* Inner loop walks contiguous memory (row-major), which
           improves cache performance and vectorization. */
        for (int j = 0; j < ny_; j++)
        {
          ey_row[j] = ey_row[j] - half * (hz_row[j] - hz_row_prev[j]);
        }
      }

      /* 3. Update ex.
         ex[i][j] depends only on ex[i][j], hz[i][j], and hz[i][j-1],
         so all (i,j) points are again independent. */
#pragma omp for schedule(static)
      for (int i = 0; i < nx_; i++)
      {
        DATA_TYPE * restrict ex_row = ex[i];
        DATA_TYPE * restrict hz_row = hz[i];

        for (int j = 1; j < ny_; j++)
        {
          ex_row[j] = ex_row[j] - half * (hz_row[j] - hz_row[j - 1]);
        }
      }

      /* 4. Update hz.
         Each hz[i][j] depends only on hz[i][j] and its neighboring
         ex, ey values, but not on neighboring hz values, so we are free
         to reorder the (i,j) iterations.  We exploit this by tiling
         (blocking) in both spatial dimensions to improve temporal
         locality of ex, ey, and hz for large grids. */
#pragma omp for collapse(2) schedule(static)
      for (int ii = 0; ii < nx_ - 1; ii += FDTD_BLOCK_I)
      {
        for (int jj = 0; jj < ny_ - 1; jj += FDTD_BLOCK_J)
        {
          const int i_max = (ii + FDTD_BLOCK_I < nx_ - 1) ? (ii + FDTD_BLOCK_I) : (nx_ - 1);
          const int j_max = (jj + FDTD_BLOCK_J < ny_ - 1) ? (jj + FDTD_BLOCK_J) : (ny_ - 1);

          for (int i = ii; i < i_max; i++)
          {
            DATA_TYPE * restrict hz_row      = hz[i];
            DATA_TYPE * restrict ex_row      = ex[i];
            DATA_TYPE * restrict ey_row      = ey[i];
            DATA_TYPE * restrict ey_row_next = ey[i + 1];

            for (int j = jj; j < j_max; j++)
            {
              hz_row[j] = hz_row[j]
                        - c0_7 * ((ex_row[j + 1] - ex_row[j]) +
                                  (ey_row_next[j] - ey_row[j]));
            }
          }
        }
      }
      /* There is an implicit barrier at the end of each 'omp for',
         so all updates for time step t complete before any thread
         proceeds to t+1. */
    }
  }

#pragma endscop
}


