/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use of `restrict` and `__builtin_assume_aligned` to remove
     aliasing and inform the compiler about memory alignment.
   - Pointer-based row access to avoid repeated 2D index arithmetic.
   - i-dimension blocking (FDTD2D_BLOCK_I) for better cache locality.
   - Explicit vectorization hints (`#pragma GCC ivdep` and unroll).
   - All transformations preserve the original numerical semantics:
     * Loop nests over i and j remain mathematically independent.
     * Time loop (t) order is unchanged.
     * No fusion across loops that would change dependence ordering.
*/
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  /* Loop bounds used by PolyBench; may be smaller than the full
     allocated sizes if POLYBENCH_LOOP_BOUND is configured that way. */
  const int TMAX_ = _PB_TMAX;
  const int NX_   = _PB_NX;
  const int NY_   = _PB_NY;

  /* Convert array parameters to restrict-qualified, aligned pointers.
     - ny is the *true* second dimension of the allocated arrays and
       must be used for the VLA types.
     - We assume POLYBENCH's alignment, exposed via POLYBENCH_ALIGNMENT. */
  DATA_TYPE (*restrict ex_)[ny] =
    (DATA_TYPE (*restrict)[ny]) __builtin_assume_aligned(ex,  FDTD2D_ALIGNMENT);
  DATA_TYPE (*restrict ey_)[ny] =
    (DATA_TYPE (*restrict)[ny]) __builtin_assume_aligned(ey,  FDTD2D_ALIGNMENT);
  DATA_TYPE (*restrict hz_)[ny] =
    (DATA_TYPE (*restrict)[ny]) __builtin_assume_aligned(hz,  FDTD2D_ALIGNMENT);
  DATA_TYPE *restrict fict_ =
    (DATA_TYPE *restrict)       __builtin_assume_aligned(_fict_, FDTD2D_ALIGNMENT);

  /* Hoist scalar constants out of the loops. */
  const DATA_TYPE c0 = SCALAR_VAL(0.5);
  const DATA_TYPE c1 = SCALAR_VAL(0.7);

  (void)tmax; /* parameters tmax, nx, ny are unused in the optimized body
                 because PolyBench driving macros (_PB_*) are used instead. */
  (void)nx;
  (void)ny;

#pragma scop

  for (int t = 0; t < TMAX_; t++)
    {
      const DATA_TYPE fict_val = fict_[t];

      /* ------------------------------------------------------------------
       * ey[0][j] = _fict_[t]  for all j
       * ----------------------------------------------------------------*/
      {
        DATA_TYPE *restrict ey0 = ey_[0];

        /* Inner loop is a simple streaming store; no dependencies. */
        #pragma GCC ivdep
        #pragma GCC unroll 8
        for (int j = 0; j < NY_; j++)
          ey0[j] = fict_val;
      }

      /* ------------------------------------------------------------------
       * ey[i][j] update for i >= 1:
       * ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j])
       * Each (i,j) iteration is independent; safe to block and vectorize.
       * ----------------------------------------------------------------*/
      for (int i_block = 1; i_block < NX_; i_block += FDTD2D_BLOCK_I)
      {
        const int i_end = (i_block + FDTD2D_BLOCK_I < NX_) ?
                          (i_block + FDTD2D_BLOCK_I) : NX_;

        for (int i = i_block; i < i_end; i++)
        {
          DATA_TYPE *restrict ey_row  = ey_[i];
          DATA_TYPE *restrict hz_row  = hz_[i];
          DATA_TYPE *restrict hz_prev = hz_[i-1];

          #pragma GCC ivdep
          #pragma GCC unroll 8
          for (int j = 0; j < NY_; j++)
          {
            ey_row[j] -= c0 * (hz_row[j] - hz_prev[j]);
          }
        }
      }

      /* ------------------------------------------------------------------
       * ex[i][j] update for j >= 1:
       * ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1])
       * Implemented using a rolling "previous hz" variable to avoid
       * re-indexing hz[i][j-1].
       * ----------------------------------------------------------------*/
      for (int i_block = 0; i_block < NX_; i_block += FDTD2D_BLOCK_I)
      {
        const int i_end = (i_block + FDTD2D_BLOCK_I < NX_) ?
                          (i_block + FDTD2D_BLOCK_I) : NX_;

        for (int i = i_block; i < i_end; i++)
        {
          DATA_TYPE *restrict ex_row = ex_[i];
          DATA_TYPE *restrict hz_row = hz_[i];

          DATA_TYPE hz_prev = hz_row[0];

          #pragma GCC ivdep
          #pragma GCC unroll 8
          for (int j = 1; j < NY_; j++)
          {
            const DATA_TYPE hz_curr = hz_row[j];
            ex_row[j] -= c0 * (hz_curr - hz_prev);
            hz_prev    = hz_curr;
          }
        }
      }

      /* ------------------------------------------------------------------
       * hz[i][j] update for 0 <= i < NX_-1, 0 <= j < NY_-1:
       * hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j] +
       *                    ey[i+1][j] - ey[i][j]);
       *
       * This uses ex and ey values computed above for the current t-step.
       * Within this loop nest:
       *   - ex and ey are only read.
       *   - hz is updated in-place but each (i,j) only depends on hz[i][j].
       * Therefore, all iterations are independent and can be safely
       * blocked and vectorized.
       * ----------------------------------------------------------------*/
      for (int i_block = 0; i_block < NX_ - 1; i_block += FDTD2D_BLOCK_I)
      {
        const int i_end = (i_block + FDTD2D_BLOCK_I < (NX_ - 1)) ?
                          (i_block + FDTD2D_BLOCK_I) : (NX_ - 1);

        for (int i = i_block; i < i_end; i++)
        {
          DATA_TYPE *restrict hz_row      = hz_[i];
          DATA_TYPE *restrict ex_row      = ex_[i];
          DATA_TYPE *restrict ey_row      = ey_[i];
          DATA_TYPE *restrict ey_row_next = ey_[i+1];

          /* Keep ex[i][j] in a rolling scalar to avoid re-reading it
             when computing ex[i][j+1] - ex[i][j]. */
          DATA_TYPE ex_j = ex_row[0];

          #pragma GCC ivdep
          #pragma GCC unroll 8
          for (int j = 0; j < NY_ - 1; j++)
          {
            const DATA_TYPE ex_jp1 = ex_row[j+1];
            const DATA_TYPE ey_j   = ey_row[j];
            const DATA_TYPE ey1_j  = ey_row_next[j];

            const DATA_TYPE curl_e = (ex_jp1 - ex_j) + (ey1_j - ey_j);
            hz_row[j] -= c1 * curl_e;

            ex_j = ex_jp1;
          }
        }
      }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

